"""App Service 'Secure unique default hostname' (properties.autoGeneratedDomainNameLabelScope) —
core/azure_webapp_core.py. Run: python3 tests/conformance/test_azure_webapp_hostname.py"""
import os
import sys

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", ".."))
from core import azure_webapp_core as wc  # noqa: E402
from core import azure_webdeploy_core  # noqa: E402,F401

PASS = FAIL = 0


def check(name, ok, detail=""):
    global PASS, FAIL
    PASS, FAIL = PASS + (1 if ok else 0), FAIL + (0 if ok else 1)
    print(f"[{'PASS' if ok else 'FAIL'}] {name}{' - ' + str(detail) if detail and not ok else ''}")


def call(st, method, chain, body=None, sub="sub1", rg="rg1"):
    return wc.dispatch(st, method, sub, rg, chain, [], body or {})


def mk(st, name, scope=None, loc="eastus", sub="sub1", rg="rg1"):
    props = {"autoGeneratedDomainNameLabelScope": scope} if scope else {}
    return call(st, "PUT", ["sites", name], {"location": loc, "kind": "app,linux", "properties": props}, sub=sub, rg=rg)


st = {}
r = mk(st, "plain1")
p = r["body"]["properties"]
check("no scope: classic host, no property echoed", p["defaultHostName"] == "plain1.azurewebsites.net"
      and "autoGeneratedDomainNameLabelScope" not in p, p)

r = mk(st, "uniq1", "TenantReuse")
p = r["body"]["properties"]
host = p["defaultHostName"]
import re  # noqa: E402
check("TenantReuse: <name>-<hash>.<region>-01.azurewebsites.net", re.fullmatch(r"uniq1-[0-9a-f]{10}\.eastus-01\.azurewebsites\.net", host), host)
check("scope is returned on the site", p["autoGeneratedDomainNameLabelScope"] == "TenantReuse")
check("hostNames/enabledHostNames/sslState agree with defaultHostName",
      p["hostNames"] == [host] and host in p["enabledHostNames"] and p["defaultHostNameSslState"]["name"] == host
      and any(".scm." in h for h in p["enabledHostNames"]), p)
g = call(st, "GET", ["sites", "uniq1"])["body"]["properties"]
check("GET returns the same hostname", g["defaultHostName"] == host and g["hostNames"] == [host])
check("site list returns it too", any(s["properties"]["defaultHostName"] == host for s in call(st, "GET", ["sites"])["body"]["value"]))

# determinism + scope semantics
t_other_sub = mk({}, "uniq1", "TenantReuse", sub="sub2", rg="rg9")["body"]["properties"]["defaultHostName"]
check("TenantReuse hash is the same across subscriptions/resource groups", t_other_sub == host, t_other_sub)
s_a = mk({}, "n1", "SubscriptionReuse", rg="rgA")["body"]["properties"]["defaultHostName"]
s_b = mk({}, "n1", "SubscriptionReuse", rg="rgB")["body"]["properties"]["defaultHostName"]
s_c = mk({}, "n1", "SubscriptionReuse", sub="sub2", rg="rgA")["body"]["properties"]["defaultHostName"]
check("SubscriptionReuse: same across RGs, differs across subscriptions", s_a == s_b and s_a != s_c, (s_a, s_b, s_c))
r_a = mk({}, "n1", "ResourceGroupReuse", rg="rgA")["body"]["properties"]["defaultHostName"]
r_a2 = mk({}, "n1", "ResourceGroupReuse", rg="rgA")["body"]["properties"]["defaultHostName"]
r_b = mk({}, "n1", "ResourceGroupReuse", rg="rgB")["body"]["properties"]["defaultHostName"]
check("ResourceGroupReuse: deterministic within an RG, differs across RGs", r_a == r_a2 and r_a != r_b)
check("different scopes give different hashes for the same name", len({host.split(".")[0], s_a.split(".")[0], r_a.split(".")[0]}) == 3)
n1 = mk({}, "n1", "NoReuse")["body"]["properties"]["defaultHostName"]
n2 = mk({}, "n1", "NoReuse")["body"]["properties"]["defaultHostName"]
check("NoReuse: a re-created app gets a different hash", n1 != n2, (n1, n2))
check("region is in the host", ".westeurope-01." in mk({}, "w1", "TenantReuse", loc="westeurope")["body"]["properties"]["defaultHostName"])

# validation
bad = mk(st, "bad1", "Whatever")
check("invalid scope is rejected with 400 InvalidParameter", bad["status"] == 400 and bad["body"]["error"]["code"] == "InvalidParameter", bad)
check("rejected site was not created", call(st, "GET", ["sites", "bad1"])["status"] == 404)
ch = call(st, "PATCH", ["sites", "uniq1"], {"properties": {"autoGeneratedDomainNameLabelScope": "NoReuse"}})
check("scope cannot change after create", ch["status"] == 400, ch)
ok = call(st, "PATCH", ["sites", "uniq1"], {"properties": {"autoGeneratedDomainNameLabelScope": "TenantReuse", "httpsOnly": True}})
check("re-sending the same scope is fine and the host is unchanged", ok["status"] == 200
      and call(st, "GET", ["sites", "uniq1"])["body"]["properties"]["defaultHostName"] == host)
put2 = call(st, "PUT", ["sites", "uniq1"], {"location": "eastus", "properties": {"autoGeneratedDomainNameLabelScope": "TenantReuse"}})
check("idempotent PUT keeps the hostname", put2["body"]["properties"]["defaultHostName"] == host)

# consistency of derived URLs
pub = call(st, "POST", ["sites", "uniq1", "publishxml"])["body"]["value"]
scm = host.split(".")[0] + ".scm." + host.split(".", 1)[1]
check("publish profile uses the unique default + scm host", f'destinationAppUrl="https://{host}"' in pub and f'publishUrl="{scm}:443"' in pub, pub)
sl = call(st, "PUT", ["sites", "uniq1", "slots", "stage"], {})["body"]["properties"]["defaultHostName"]
check("slot host is <name>-<slot>-<hash>.<region>-01", re.fullmatch(r"uniq1-stage-[0-9a-f]{10}\.eastus-01\.azurewebsites\.net", sl), sl)
c = call(st, "PUT", ["sites", "uniq1", "hostNameBindings", "www.example.com"], {})
hn = call(st, "GET", ["sites", "uniq1"])["body"]["properties"]["hostNames"]
check("custom domain is added next to the unique default host", c["status"] in (200, 201) and host in hn and "www.example.com" in hn, hn)
rec = st[wc._canon("sub1", "rg1", ["sites"], ["uniq1"]).lower()]
cr = azure_webdeploy_core.dispatch(st, rec, ["config", "publishingcredentials", "list"], "POST", {})
body = cr.get("body") if isinstance(cr, dict) else None
check("publishingcredentials scmUri uses the unique scm host", body and scm in body["properties"]["scmUri"], cr)
print(f"\n{PASS} passed, {FAIL} failed")
sys.exit(1 if FAIL else 0)
